 const example = `<script lang="ts">\n  import { Button, Input, Label } from 'twenty-svelte';\n<\/script>\n\n<Label for="name">Name</Label>\n<Input id="name" placeholder="Ada Lovelace" />\n<Button>Save contact</Button>`;
